/**
 * VISÃO - Coverage Dashboard
 * Visualizes per-file test coverage produced by `npm run coverage`.
 *
 * Source: /coverage-report.json (generated by scripts/build-coverage-report.mjs).
 */

import { useQuery } from '@tanstack/react-query';
import { Download, ExternalLink, RefreshCw, TestTube2 } from 'lucide-react';
import { format, formatDistanceToNow } from 'date-fns';
import { ptBR } from 'date-fns/locale';

import { PageMeta } from '@/components/PageMeta';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { CoverageStatsCards, CoverageTable } from '@/components/coverage';
import { downloadCoverageTextReport } from '@/lib/coverageTextReport';
import { parseCoverageReport, type ParseCoverageResult } from '@/lib/coverageSchema';
import type { CoverageReport } from '@/types/coverage';

const COVERAGE_URL = '/coverage-report.json';

const fetchCoverage = async (): Promise<ParseCoverageResult | null> => {
  const res = await fetch(`${COVERAGE_URL}?t=${Date.now()}`, {
    headers: { Accept: 'application/json' },
  });
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Falha ao carregar coverage (${res.status})`);
  let raw: unknown;
  try {
    raw = await res.json();
  } catch (e) {
    throw new Error(`JSON inválido em ${COVERAGE_URL}: ${(e as Error).message}`, { cause: e });
  }
  return parseCoverageReport(raw);
};

const CoveragePage = () => {
  const {
    data: parsed,
    isLoading,
    isError,
    error,
    refetch,
    isFetching,
  } = useQuery({
    queryKey: ['coverage-report'],
    queryFn: fetchCoverage,
    staleTime: 60_000,
    retry: 1,
  });

  const data: CoverageReport | undefined = parsed?.report;
  const degraded = parsed?.degraded ?? false;
  const warnings = parsed?.warnings ?? [];

  return (
    <div className="space-y-6 p-4 md:p-6">
      <PageMeta
        title="Cobertura de Testes"
        description="Dashboard de cobertura de testes por arquivo do sistema VISÃO."
      />

      <header className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <TestTube2 className="h-5 w-5 text-primary" aria-hidden />
            <h1 className="text-2xl font-bold tracking-tight">Cobertura de Testes</h1>
          </div>
          <p className="text-sm text-muted-foreground">
            Percentual de cobertura de testes por arquivo. Use para priorizar onde adicionar novos
            testes.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => refetch()} disabled={isFetching}>
            <RefreshCw className={isFetching ? 'mr-2 h-4 w-4 animate-spin' : 'mr-2 h-4 w-4'} />
            Atualizar
          </Button>
          {data && (
            <>
              <Button variant="outline" size="sm" onClick={() => downloadCoverageTextReport(data)}>
                <Download className="mr-2 h-4 w-4" />
                Baixar .txt consolidado
              </Button>
              <Button asChild variant="outline" size="sm">
                <a
                  href={
                    import.meta.env.VITE_COVERAGE_HTML_ARTIFACTS_URL ??
                    'https://github.com/?q=coverage.yml'
                  }
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label="Baixar relatório HTML completo (artifact do CI)"
                >
                  <ExternalLink className="mr-2 h-4 w-4" />
                  Baixar HTML completo (CI)
                </a>
              </Button>
            </>
          )}
        </div>
      </header>

      {isLoading && (
        <Card>
          <CardContent
            className="p-12 text-center text-sm text-muted-foreground"
            role="status"
            aria-live="polite"
            aria-busy="true"
            aria-label="Carregando relatório de cobertura…"
          >
            Carregando relatório de cobertura…
            <span className="sr-only">Carregando relatório de cobertura…</span>
          </CardContent>
        </Card>
      )}

      {isError && (
        <Alert variant="destructive">
          <AlertTitle>Erro ao carregar cobertura</AlertTitle>
          <AlertDescription>
            {error instanceof Error ? error.message : 'Erro desconhecido.'}
          </AlertDescription>
        </Alert>
      )}

      {!isLoading && !isError && !data && (
        <Card>
          <CardContent className="space-y-3 p-8 text-center">
            <TestTube2 className="mx-auto h-10 w-10 text-muted-foreground" aria-hidden />
            <h2 className="text-lg font-semibold">Nenhum relatório encontrado</h2>
            <p className="mx-auto max-w-md text-sm text-muted-foreground">
              Execute{' '}
              <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-xs">
                npm run coverage
              </code>{' '}
              localmente ou aguarde a próxima execução do workflow{' '}
              <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-xs">coverage.yml</code>{' '}
              para gerar o dashboard.
            </p>
          </CardContent>
        </Card>
      )}

      {data && (
        <>
          {degraded && warnings.length > 0 && (
            <Alert variant="destructive">
              <AlertTitle>Relatório carregado com avisos</AlertTitle>
              <AlertDescription>
                O JSON tem campos ausentes/inválidos. Fallbacks foram aplicados; números podem estar
                incompletos.
                <ul className="mt-2 list-inside list-disc text-xs">
                  {warnings.map((w) => (
                    <li key={w}>{w}</li>
                  ))}
                </ul>
              </AlertDescription>
            </Alert>
          )}
          {data.alert?.dropExceeded && data.alert.delta !== null && (
            <Alert variant="destructive">
              <AlertTitle>⚠️ Queda de cobertura detectada</AlertTitle>
              <AlertDescription>
                A cobertura global de statements caiu{' '}
                <strong>{Math.abs(data.alert.delta).toFixed(2)} pp</strong>
                {data.alert.previousPct !== null && (
                  <>
                    {' '}
                    (de <strong>{data.alert.previousPct.toFixed(2)}%</strong> para{' '}
                    <strong>{data.totals.statements.pct.toFixed(2)}%</strong>)
                  </>
                )}
                , ultrapassando o limite de <strong>{data.alert.threshold.toFixed(2)} pp</strong>.
                Adicione testes para os arquivos listados abaixo antes de mesclar.
              </AlertDescription>
            </Alert>
          )}
          {data.alert &&
            !data.alert.dropExceeded &&
            data.alert.delta !== null &&
            data.alert.delta < 0 && (
              <Alert>
                <AlertTitle className="text-sm">📉 Cobertura caiu levemente</AlertTitle>
                <AlertDescription>
                  Variação de <strong>{data.alert.delta.toFixed(2)} pp</strong> vs. execução
                  anterior (limite de alerta: {data.alert.threshold.toFixed(2)} pp).
                </AlertDescription>
              </Alert>
            )}
          <Alert>
            <AlertTitle className="text-sm">
              Última execução:{' '}
              <span className="font-mono">
                {format(new Date(data.generatedAt), 'dd/MM/yyyy HH:mm', { locale: ptBR })}
              </span>{' '}
              <span className="font-normal text-muted-foreground">
                (
                {formatDistanceToNow(new Date(data.generatedAt), { locale: ptBR, addSuffix: true })}
                )
              </span>
            </AlertTitle>
            <AlertDescription>
              {data.files.length.toLocaleString('pt-BR')} arquivos analisados. Cobertura global de
              statements: <strong>{data.totals.statements.pct.toFixed(2)}%</strong>
              {data.alert?.delta !== null && data.alert?.delta !== undefined && (
                <>
                  {' '}
                  {/* eslint-disable-next-line visao/no-hardcoded-colors -- semântica positivo/negativo via paleta tailwind */}
                  <span className={data.alert.delta >= 0 ? 'text-success' : 'text-destructive'}>
                    ({data.alert.delta >= 0 ? '+' : ''}
                    {data.alert.delta.toFixed(2)} pp vs. anterior)
                  </span>
                </>
              )}
              .
            </AlertDescription>
          </Alert>

          <CoverageStatsCards totals={data.totals} />

          <CoverageTable files={data.files} />
        </>
      )}
    </div>
  );
};

export default CoveragePage;
